    /// <param name="option"><see href="https://drafts.csswg.org/css-spatial-nav-1/#dom-element-focusableareas-option-option">CSS Spatial Navigation Module Level 1: 5.2 Low level APIs</see></param>
    [Description("@#focusableAreas")]
    public extern Node[] FocusableAreas(FocusableAreasOption? option = default);

    /// <summary>
    /// JavaScript Element.spatialNavigationSearch(dir, options) 的强类型绑定，WebIDL 返回类型为 Node?。
    /// </summary>
    /// <remarks>
    /// <see href="https://drafts.csswg.org/css-spatial-nav-1/#dom-element-spatialnavigationsearch">CSS Spatial Navigation Module Level 1: 5.2 Low level APIs</see>
    /// </remarks>
    /// <param name="dir"><see href="https://drafts.csswg.org/css-spatial-nav-1/#dom-element-spatialnavigationsearch-dir-options-dir">CSS Spatial Navigation Module Level 1: 5.2 Low level APIs</see></param>
    /// <param name="options"><see href="https://drafts.csswg.org/css-spatial-nav-1/#dom-element-spatialnavigationsearch-dir-options-options">CSS Spatial Navigation Module Level 1: 5.2 Low level APIs</see></param>
    [Description("@#spatialNavigationSearch")]
    public extern Node? SpatialNavigationSearch(SpatialNavigationDirection dir, SpatialNavigationSearchOptions? options = default);

    /// <summary>
    /// Changed window.getPseudoElements(elem,type) to Element.pseudo(type).
    /// </summary>
    /// <remarks>
