[Description("@#CSSLayerStatementRule")]
public class CSSLayerStatementRule : CSSRule
{
    /// <summary>
    /// The read-only nameList property of the CSSLayerStatementRule interface returns the list of associated cascade layer names. The names can&apos;t be modified.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CSSLayerStatementRule/nameList">MDN Web Docs: CSSLayerStatementRule.nameList</see>
    /// </remarks>
    [Description("@#nameList")]
    public extern FrozenSet<string> NameList { get; }
}

