[ECMAScript]
[Description("@#HTMLElement")]
public partial class HTMLElement : Element
{
    /// <summary>
    /// JavaScript 属性 HTMLElement.containerTiming：DOMString。可读取或赋值；赋值按 WebIDL 类型转换规则处理。
    /// </summary>
    /// <remarks>
