[Description("@#PageRevealEvent")]
public class PageRevealEvent(string type, EventInit eventInitDict) : EventRef(type, eventInitDict)
{
    /// <summary>
    /// The PageRevealEvent() constructor creates a new PageRevealEvent object instance.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/PageRevealEvent/PageRevealEvent">MDN Web Docs: PageRevealEvent.PageRevealEvent</see>
    /// </remarks>
    /// <param name="type">A string representing the type of event. In the case of PageRevealEvent this is always pagereveal. <see href="https://developer.mozilla.org/en-US/docs/Web/API/PageRevealEvent/PageRevealEvent">MDN Web Docs: type</see></param>
    /// <param name="eventInitDict">WebIDL 参数 eventInitDict：PageRevealEventInit。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;dictionary&quot;&#10;                    }。 <see href="https://developer.mozilla.org/en-US/docs/Web/API/PageRevealEvent/PageRevealEvent">MDN Web Docs: eventInitDict</see></param>
public extern PageRevealEvent(string type, PageRevealEventInit? eventInitDict = default);

    /// <summary>
    /// The viewTransition attribute must return the value it was initialized to.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/nav-history-apis.html#dom-pagerevealevent-viewtransition">HTML Standard: 7.2.7.5 The PageRevealEvent interface</see>
    /// </remarks>
    /// <example>
    /// <code>event.viewTransition</code>
    /// </example>
    [Description("@#viewTransition")]
    public extern ViewTransition? ViewTransition { get; }
}

