    /// <param name="bubbles">WebIDL 参数 bubbles：boolean。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;boolean&quot;,&#10;                      &quot;value&quot;: false&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: bubbles</see></param>
    /// <param name="cancelable">WebIDL 参数 cancelable：boolean。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;boolean&quot;,&#10;                      &quot;value&quot;: false&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: cancelable</see></param>
    /// <param name="key">WebIDL 参数 key：DOMString?。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;null&quot;&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: key</see></param>
    /// <param name="oldValue">WebIDL 参数 oldValue：DOMString?。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;null&quot;&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: oldValue</see></param>
    /// <param name="newValue">WebIDL 参数 newValue：DOMString?。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;null&quot;&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: newValue</see></param>
    /// <param name="url">WebIDL 参数 url：USVString。可省略。WebIDL 默认值：。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: url</see></param>
    /// <param name="storageArea">WebIDL 参数 storageArea：Storage?。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;null&quot;&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-storageevent-initstorageevent">HTML Standard: storageArea</see></param>
    [Description("@#initStorageEvent")]
    public extern void InitStorageEvent(string type, bool bubbles = false, bool cancelable = false, string? key = default, string? oldValue = default, string? newValue = default, string url = "", Storage? storageArea = default);
