    [Description("@#cancelAnimationFrame")]
    public extern void CancelAnimationFrame(uint handle);
    #endregion

    #region mixin MessageEventTarget
    /// <summary>
    /// Certain event handler IDL attributes have additional requirements, in particular the onmessage attribute of MessagePort objects.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/web-messaging.html#handler-messageeventtarget-onmessage">HTML Standard: 9.4.3 The MessageEventTarget mixin</see>
    /// </remarks>
    [Description("@#onmessage")]
    public extern EventHandler Onmessage { get; set; }

    /// <summary>
    /// JavaScript 属性 MessageEventTarget.onmessageerror：EventHandler。可读取或赋值；赋值按 WebIDL 类型转换规则处理。
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/web-messaging.html#handler-messageeventtarget-onmessageerror">HTML Standard: 9.4.3 The MessageEventTarget mixin</see>
