    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/XRRenderState/baseLayer">MDN Web Docs: XRRenderState.baseLayer</see>
    /// </remarks>
    [Description("@#baseLayer")]
    public extern XRWebGLLayer? BaseLayer { get; }

    /// <summary>
