    /// </remarks>
    /// <param name="options"><see href="https://w3c-fedid.github.io/FedCM/#dom-identitycredential-disconnect-options-options">Federated Credential Management API: 2.2 The IdentityCredential Interface</see></param>
    [Description("@#disconnect")]
