    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/ServiceWorkerRegistration/periodicSync">MDN Web Docs: ServiceWorkerRegistration.periodicSync</see>
    /// </remarks>
    [Description("@#periodicSync")]
    public extern PeriodicSyncManager PeriodicSync { get; }

