    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/MouseEvent/x">MDN Web Docs: MouseEvent.x</see>
    /// </remarks>
    [Description("@#x")]
    public extern double X { get; }

    /// <summary>
    /// The MouseEvent.y property is an alias for the MouseEvent.clientY property.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/MouseEvent/y">MDN Web Docs: MouseEvent.y</see>
    /// </remarks>
    [Description("@#y")]
    public extern double Y { get; }

    /// <summary>
    /// The offsetX read-only property of the MouseEvent interface provides the offset in the X coordinate of the mouse pointer between that event and the padding edge of the target node.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/MouseEvent/offsetX">MDN Web Docs: MouseEvent.offsetX</see>
