    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/presentation-api/#dom-presentation-receiver">Presentation API: 6.2.2 Receiving user agent</see>
    /// </remarks>
    [Description("@#receiver")]
    public extern PresentationReceiver? Receiver { get; }
}

/// <summary>
