/// </summary>
/// <remarks>
/// <see href="https://developer.mozilla.org/en-US/docs/Web/API/PresentationRequest">MDN Web Docs: PresentationRequest</see>
/// </remarks>
[ECMAScript]
[Description("@#PresentationRequest")]
public class PresentationRequest : EventTarget
{
