    /// <param name="elementNs"><see href="https://w3c.github.io/trusted-types/dist/spec/#dom-trustedtypepolicyfactory-getattributetype-tagname-attribute-elementns-attrns-elementns">Trusted Types: 2.3.1 TrustedTypePolicyFactory</see></param>
    /// <param name="attrNs"><see href="https://w3c.github.io/trusted-types/dist/spec/#dom-trustedtypepolicyfactory-getattributetype-tagname-attribute-elementns-attrns-attrns">Trusted Types: 2.3.1 TrustedTypePolicyFactory</see></param>
    /// <returns>A string with one of: &quot;TrustedHTML&quot; &quot;TrustedScript&quot; &quot;TrustedScriptURL&quot; Or, null.</returns>
    [Description("@#getAttributeType")]
    public extern string? GetAttributeType(string tagName, string attribute, string? elementNs = "", string? attrNs = "");

    /// <summary>
    /// Note: This feature is available in Web Workers. The getPropertyType() method of the TrustedTypePolicyFactory interface allows web developers to check if a Trusted Type is required for an element&apos;s property.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/TrustedTypePolicyFactory/getPropertyType">MDN Web Docs: TrustedTypePolicyFactory.getPropertyType</see>
    /// </remarks>
    /// <param name="tagName">A string containing the name of an HTML tag. <see href="https://developer.mozilla.org/en-US/docs/Web/API/TrustedTypePolicyFactory/getPropertyType">MDN Web Docs: tagName</see></param>
    /// <param name="property">A string containing a property, for example &quot;innerHTML&quot;. <see href="https://developer.mozilla.org/en-US/docs/Web/API/TrustedTypePolicyFactory/getPropertyType">MDN Web Docs: property</see></param>
    /// <param name="elementNs"><see href="https://w3c.github.io/trusted-types/dist/spec/#dom-trustedtypepolicyfactory-getpropertytype-tagname-property-elementns-elementns">Trusted Types: 2.3.1 TrustedTypePolicyFactory</see></param>
    /// <returns>A string with one of: &quot;TrustedHTML&quot; &quot;TrustedScript&quot; &quot;TrustedScriptURL&quot; Or, null.</returns>
    [Description("@#getPropertyType")]
    public extern string? GetPropertyType(string tagName, string property, string? elementNs = "");

    /// <summary>
