    /// </remarks>
    [Description("@#onspeechend")]
    public extern EventHandler Onspeechend { get; set; }

    /// <summary>
    /// The soundend event of the Web Speech API is fired when any sound — recognizable speech or not — has stopped being detected.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/SpeechRecognition/soundend_event">MDN Web Docs: SpeechRecognition.onsoundend</see>
    /// </remarks>
    [Description("@#onsoundend")]
    public extern EventHandler Onsoundend { get; set; }

