    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/IdleDetector/screenState">MDN Web Docs: IdleDetector.screenState</see>
    /// </remarks>
    [Description("@#screenState")]
