    /// <param name="style">An object defining the trail style, which contains the following properties: color A String containing a valid CSS color code, indicating the color the presenter will use when rendering the ink trail. diameter A number representing the diameter the presenter will use when rendering the ink trail. <see href="https://developer.mozilla.org/en-US/docs/Web/API/DelegatedInkTrailPresenter/updateInkTrailStartPoint">MDN Web Docs: style</see></param>
    [Description("@#updateInkTrailStartPoint")]
    public extern void UpdateInkTrailStartPoint(PointerEvent @event, InkTrailStyle style);
}

