/// <summary>
/// CharacterData is an abstract interface. You cannot get a direct instance of it. It is used by Text, ProcessingInstruction, and Comment nodes.
/// </summary>
/// <remarks>
/// <see href="https://dom.spec.whatwg.org/#characterdata">DOM Standard: 4.10 Interface CharacterData</see>
/// </remarks>
[ECMAScript]
[Description("@#CharacterData")]
public class CharacterData : Node
{
    /// <summary>
    /// The data property of the CharacterData interface represents the value of the current object&apos;s data.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/data">MDN Web Docs: CharacterData.data</see>
    /// </remarks>
    [Description("@#data")]
    public extern string Data { get; set; }

    /// <summary>
    /// If node is a CharacterData node, then return node&apos;s data&apos;s length.
    /// </summary>
    /// <remarks>
    /// <see href="https://dom.spec.whatwg.org/#dom-characterdata-length">DOM Standard: 4.10 Interface CharacterData</see>
    /// </remarks>
    [Description("@#length")]
    public extern uint Length { get; }

    /// <summary>
    /// The substringData() method of the CharacterData interface returns a portion of the existing data, starting at the specified index and extending for a given number of characters afterwards.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/substringData">MDN Web Docs: CharacterData.substringData</see>
    /// </remarks>
    /// <param name="offset">The index of the first character to include in the returned substring. 0 is the first character of the string. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/substringData">MDN Web Docs: offset</see></param>
    /// <param name="count">The number of characters to return. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/substringData">MDN Web Docs: count</see></param>
    /// <returns>A string with the substring.</returns>
    [Description("@#substringData")]
    public extern string SubstringData(uint offset, uint count);

    /// <summary>
    /// The appendData() method of the CharacterData interface adds the provided data to the end of the node&apos;s current data.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/appendData">MDN Web Docs: CharacterData.appendData</see>
    /// </remarks>
    /// <param name="data">The data to append to the current node. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/appendData">MDN Web Docs: data</see></param>
    [Description("@#appendData")]
    public extern void AppendData(string data);

    /// <summary>
    /// The insertData() method of the CharacterData interface inserts the provided data into this CharacterData node&apos;s current data, at the provided offset from the start of the existing data. The provided data is spliced into the existing data.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/insertData">MDN Web Docs: CharacterData.insertData</see>
    /// </remarks>
    /// <param name="offset">The offset number of characters to insert the provided data at. 0 is the first character of the string. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/insertData">MDN Web Docs: offset</see></param>
    /// <param name="data">The data to insert. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/insertData">MDN Web Docs: data</see></param>
    [Description("@#insertData")]
    public extern void InsertData(uint offset, string data);

    /// <summary>
    /// The deleteData() method of the CharacterData interface removes all or part of the data from this CharacterData node.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/deleteData">MDN Web Docs: CharacterData.deleteData</see>
    /// </remarks>
    /// <param name="offset">The number of bytes from the start of the data to remove from. 0 is the first character of the string. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/deleteData">MDN Web Docs: offset</see></param>
    /// <param name="count">The number of bytes to remove. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/deleteData">MDN Web Docs: count</see></param>
    [Description("@#deleteData")]
    public extern void DeleteData(uint offset, uint count);

    /// <summary>
    /// The replaceData() method of the CharacterData interface removes a certain number of characters of the existing text in a given CharacterData node and replaces those characters with the text provided.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/replaceData">MDN Web Docs: CharacterData.replaceData</see>
    /// </remarks>
    /// <param name="offset">The number of characters from the start of the data to insert at. 0 is the first character of the string. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/replaceData">MDN Web Docs: offset</see></param>
    /// <param name="count">The number of characters to replace with the provided data. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/replaceData">MDN Web Docs: count</see></param>
    /// <param name="data">The data to insert. <see href="https://developer.mozilla.org/en-US/docs/Web/API/CharacterData/replaceData">MDN Web Docs: data</see></param>
    [Description("@#replaceData")]
    public extern void ReplaceData(uint offset, uint count, string data);

