    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/CSSFontFeatureValuesRule/fontFamily">MDN Web Docs: CSSFontFeatureValuesRule.fontFamily</see>
    /// </remarks>
    [Description("@#fontFamily")]
    public extern string FontFamily { get; set; }

    /// <summary>
