    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/TextTrackCue/endTime">MDN Web Docs: TextTrackCue.endTime</see>
    /// </remarks>
    [Description("@#endTime")]
