    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/TextTrackCue/enter_event">MDN Web Docs: TextTrackCue.onenter</see>
    /// </remarks>
    [Description("@#onenter")]
    public extern EventHandler Onenter { get; set; }

    /// <summary>
    /// The exit event fires when a cue stops being active.
