    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/TextTrackCue/exit_event">MDN Web Docs: TextTrackCue.onexit</see>
    /// </remarks>
    [Description("@#onexit")]
    public extern EventHandler Onexit { get; set; }
}

