    /// </remarks>
    [Description("@#onvalidationstatuschange")]
    public extern EventHandler Onvalidationstatuschange { get; set; }
    #endregion

    #region mixin PowerfulFeatureObserver
    /// <summary>
    /// JavaScript 属性 PowerfulFeatureObserver.initialPermissionStatus：PermissionState。只读；由宿主 API 提供当前值。
    /// </summary>
    /// <remarks>
    /// <see href="https://wicg.github.io/PEPC/geolocation-element.html#dom-powerfulfeatureobserver-initialpermissionstatus">The HTML Geolocation Element: 3.2.2 Algorithms</see>
