    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/pause">MDN Web Docs: HTMLMediaElement.pause</see>
    /// </remarks>
    [Description("@#pause")]
    public extern void Pause();

    /// <summary>
    /// The HTMLMediaElement.controls property reflects the controls HTML attribute, which controls whether user interface controls for playing the media item will be displayed.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/controls">MDN Web Docs: HTMLMediaElement.controls</see>
    /// </remarks>
    [Description("@#controls")]
    public extern bool Controls { get; set; }

    /// <summary>
