    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/volume">MDN Web Docs: HTMLMediaElement.volume</see>
    /// </remarks>
    [Description("@#volume")]
    public extern double Volume { get; set; }

    /// <summary>
    /// The HTMLMediaElement.muted property indicates whether the media element is muted.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/muted">MDN Web Docs: HTMLMediaElement.muted</see>
    /// </remarks>
    [Description("@#muted")]
    public extern bool Muted { get; set; }

    /// <summary>
    /// The HTMLMediaElement.defaultMuted property reflects the muted HTML attribute, which indicates whether the media element&apos;s audio output should be muted by default. This property has no dynamic effect. To mute and unmute the audio output, use the muted property.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/defaultMuted">MDN Web Docs: HTMLMediaElement.defaultMuted</see>
    /// </remarks>
    [Description("@#defaultMuted")]
    public extern bool DefaultMuted { get; set; }

    /// <summary>
    /// The loading IDL attribute must reflect the loading content attribute, limited to only known values.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/media.html#dom-media-loading">HTML Standard: 4.8.11 Media elements</see>
    /// </remarks>
    [Description("@#loading")]
    public extern string Loading { get; set; }

    /// <summary>
    /// The audioTracks attribute of a media element must return a live AudioTrackList object representing the audio tracks available in the media element&apos;s media resource.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/media.html#dom-media-audiotracks">HTML Standard: 4.8.11.10 Media resources with multiple media tracks</see>
    /// </remarks>
    /// <example>
    /// <code>media.audioTracks✔MDNHTMLMediaElement/audioTracksSupport in all current engines.Firefox🔰 33+Safari7+Chrome🔰 37+Opera?Edge🔰 79+Edge (Legacy)NoInternet Explorer10+Firefox Android?Safari iOS?Chrome Android?WebView Android?Samsung Internet?Opera Android?</code>
    /// </example>
    [Description("@#audioTracks")]
    public extern AudioTrackList AudioTracks { get; }

    /// <summary>
    /// The videoTracks attribute of a media element must return a live VideoTrackList object representing the video tracks available in the media element&apos;s media resource.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/media.html#dom-media-videotracks">HTML Standard: 4.8.11.10 Media resources with multiple media tracks</see>
    /// </remarks>
    /// <example>
    /// <code>media.videoTracks✔MDNHTMLMediaElement/videoTracksSupport in all current engines.Firefox🔰 33+Safari7+Chrome🔰 37+Opera?Edge🔰 79+Edge (Legacy)NoInternet ExplorerNoFirefox Android?Safari iOS?Chrome Android?WebView Android?Samsung Internet?Opera Android?</code>
    /// </example>
    [Description("@#videoTracks")]
    public extern VideoTrackList VideoTracks { get; }

    /// <summary>
    /// The textTracks attribute of media elements must return a TextTrackList object representing the text tracks in the media element&apos;s list of text tracks, in the same order as in the list of text tracks.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/media.html#dom-media-texttracks">HTML Standard: 4.8.11.11.5 Text track API</see>
    /// </remarks>
    /// <example>
    /// <code>media.textTracks.length✔MDNHTMLMediaElement/textTracksSupport in all current engines.Firefox31+Safari6+Chrome23+Opera12.1+Edge79+Edge (Legacy)12+Internet Explorer10+Firefox Android?Safari iOS?Chrome Android?WebView Android?Samsung Internet1.0+Opera Android12.1+</code>
    /// </example>
    [Description("@#textTracks")]
    public extern TextTrackList TextTracks { get; }

    /// <summary>
    /// The addTextTrack() method of the HTMLMediaElement interface creates a new TextTrack object and adds it to the media element. It fires an addtrack event on this media element&apos;s textTracks. This method can&apos;t be used on a TextTrackList interface, only an HTMLMediaElement.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/addTextTrack">MDN Web Docs: HTMLMediaElement.addTextTrack</see>
    /// </remarks>
    /// <param name="kind">A string representing the TextTrack.kind property (subtitles, captions, descriptions, chapters, or metadata). <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/addTextTrack">MDN Web Docs: kind</see></param>
    /// <param name="label">A string representing the TextTrack.label property. <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/addTextTrack">MDN Web Docs: label</see></param>
    /// <param name="language">A string representing the TextTrack.language property. <see href="https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement/addTextTrack">MDN Web Docs: language</see></param>
    /// <returns>The newly created TextTrack object.</returns>
    [Description("@#addTextTrack")]
    public extern TextTrack AddTextTrack(TextTrackKind kind, string label = "", string language = "");

    /// <summary>
    /// The method captureStream is added on HTML !HTML5 media elements. Methods for capture are added to both HTMLMediaElement and HTMLCanvasElement.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/mediacapture-fromelement/#dom-htmlmediaelement-capturestream">Media Capture from DOM Elements: Methods</see>
    /// </remarks>
    [Description("@#captureStream")]
    public extern MediaStream CaptureStream();

    /// <summary>
    /// The remote read-only property of the HTMLMediaElement interface returns the RemotePlayback object associated with the media element. The RemotePlayback object allow the control of remote devices playing the media.
    /// </summary>
