/// </remarks>
[ECMAScript]
[Description("@#NodeIterator")]
public class NodeIterator
{
    /// <summary>
    /// For each NodeIterator object iterator whose root&apos;s node document is node&apos;s node document: run the NodeIterator pre-remove steps given node and iterator.
