    /// <param name="y">WebIDL 参数 y：unrestricted double。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: y</see></param>
    /// <param name="radiusX">WebIDL 参数 radiusX：unrestricted double。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: radiusX</see></param>
    /// <param name="radiusY">WebIDL 参数 radiusY：unrestricted double。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: radiusY</see></param>
    /// <param name="rotation">WebIDL 参数 rotation：unrestricted double。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: rotation</see></param>
    /// <param name="startAngle">WebIDL 参数 startAngle：unrestricted double。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: startAngle</see></param>
    /// <param name="endAngle">WebIDL 参数 endAngle：unrestricted double。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: endAngle</see></param>
    /// <param name="counterclockwise">WebIDL 参数 counterclockwise：boolean。可省略。WebIDL 默认值：{&#10;                      &quot;type&quot;: &quot;boolean&quot;,&#10;                      &quot;value&quot;: false&#10;                    }。 <see href="https://html.spec.whatwg.org/multipage/canvas.html#dom-context-2d-ellipse">HTML Standard: counterclockwise</see></param>
    [Description("@#ellipse")]
    public extern void Ellipse(double x, double y, double radiusX, double radiusY, double rotation, double startAngle, double endAngle, bool counterclockwise = false);
    #endregion
}

