/// <summary>
/// The AudioTrackList and VideoTrackList interfaces are used by attributes defined in the previous section.
/// </summary>
/// <remarks>
/// <see href="https://html.spec.whatwg.org/multipage/media.html#audiotracklist">HTML Standard: 4.8.11.10.1 AudioTrackList and VideoTrackList objects</see>
/// </remarks>
[ECMAScript]
[Description("@#AudioTrackList")]
public class AudioTrackList : EventTarget
{
    /// <summary>
    /// The AudioTrackList length and VideoTrackList length attribute getters must return the number of tracks represented by their objects at the time of getting.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/media.html#dom-audiotracklist-length">HTML Standard: 4.8.11.10.1 AudioTrackList and VideoTrackList objects</see>
    /// </remarks>
    /// <example>
    /// <code>media.audioTracks.length✔MDNAudioTrackList/lengthSupport in all current engines.Firefox🔰 33+Safari7+Chrome🔰 37+Opera?Edge🔰 79+Edge (Legacy)NoInternet Explorer10+Firefox Android?Safari iOS?Chrome Android?WebView Android?Samsung Internet?Opera Android?</code>
    /// </example>
    [Description("@#length")]
    public extern uint Length { get; }

    /// <summary>
    /// JavaScript AudioTrackList.(index) 的强类型绑定，WebIDL 返回类型为 AudioTrack。
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/">HTML Standard: AudioTrackList.</see>
    /// </remarks>
    /// <param name="index">WebIDL 参数 index：unsigned long。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/">HTML Standard: index</see></param>
[Description("@#")]
    public extern AudioTrack this[uint index] { get; }

    /// <summary>
    /// The AudioTrackList getTrackById(id) and VideoTrackList getTrackById(id) methods must return the first AudioTrack or VideoTrack object (respectively) in the AudioTrackList or VideoTrackList object (respectively) whose identifier is equal to the value of the id argument (in the natural order of the list, as defined above). When no tracks match the given argument, the methods must return null.
    /// </summary>
    /// <remarks>
    /// <see href="https://html.spec.whatwg.org/multipage/media.html#dom-audiotracklist-gettrackbyid">HTML Standard: 4.8.11.10.1 AudioTrackList and VideoTrackList objects</see>
    /// </remarks>
    /// <example>
    /// <code>audioTrack = media.audioTracks.getTrackById(id)✔MDNAudioTrackList/getTrackByIdSupport in all current engines.Firefox🔰 33+Safari7+Chrome🔰 37+Opera?Edge🔰 79+Edge (Legacy)NoInternet Explorer10+Firefox Android?Safari iOS?Chrome Android?WebView Android?Samsung Internet?Opera Android?</code>
    /// </example>
    /// <param name="id">WebIDL 参数 id：DOMString。调用时必须传入。 <see href="https://html.spec.whatwg.org/multipage/media.html#dom-audiotracklist-gettrackbyid">HTML Standard: id</see></param>
    [Description("@#getTrackById")]
    public extern AudioTrack? GetTrackById(string id);

    /// <summary>
    /// The change event is fired when an audio track is enabled or disabled, for example by changing the track&apos;s enabled property. This event is not cancelable and does not bubble.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/AudioTrackList/change_event">MDN Web Docs: AudioTrackList.onchange</see>
    /// </remarks>
    [Description("@#onchange")]
    public extern EventHandler Onchange { get; set; }

    /// <summary>
    /// The addtrack event is fired when a track is added to an AudioTrackList.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/AudioTrackList/addtrack_event">MDN Web Docs: AudioTrackList.onaddtrack</see>
    /// </remarks>
    [Description("@#onaddtrack")]
    public extern EventHandler Onaddtrack { get; set; }

    /// <summary>
    /// The removetrack event is fired when a track is removed from an AudioTrackList.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/AudioTrackList/removetrack_event">MDN Web Docs: AudioTrackList.onremovetrack</see>
    /// </remarks>
    [Description("@#onremovetrack")]
    public extern EventHandler Onremovetrack { get; set; }
}

