    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/ResizeObserverSize/blockSize">MDN Web Docs: ResizeObserverSize.blockSize</see>
    /// </remarks>
    [Description("@#blockSize")]
    public extern double BlockSize { get; }
}

