[ECMAScript]
[Description("@#HTMLFontElement")]
public class HTMLFontElement : HTMLElement
{
    /// <summary>
    /// 构造浏览器提供的 HTMLFontElement 对象；参数按对应 WebIDL 构造签名传递。
