    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/MediaStream/removetrack_event">MDN Web Docs: MediaStream.onremovetrack</see>
    /// </remarks>
    [Description("@#onremovetrack")]
    public extern EventHandler Onremovetrack { get; set; }
}

