    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/Element/pointerout_event">MDN Web Docs: GlobalEventHandlers.onpointerout</see>
    /// </remarks>
    [Description("@#onpointerout")]
    public extern EventHandler Onpointerout { get; set; }

    /// <summary>
