    /// <param name="init"><see href="https://fetch.spec.whatwg.org/#dom-windoworworkerglobalscope-fetch-input-init-init">Fetch Standard: 5.6 Fetch methods</see></param>
    /// <returns>A Promise that resolves to a Response object.</returns>
    [Description("@#fetch")]
    public extern PromiseResult<Response> Fetch(RequestInfo input, RequestInit? init = default);

