    [Description("@#lineWidth")]
    public extern double LineWidth { get; set; }

    /// <summary>
    /// The lineCap attribute defines the type of endings that UAs will place on the end of lines. The three valid values are &quot;butt&quot;, &quot;round&quot;, and &quot;square&quot;.
    /// </summary>
