    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/TreeWalker/nextNode">MDN Web Docs: TreeWalker.nextNode</see>
    /// </remarks>
    /// <returns>A Node object or null.</returns>
    [Description("@#nextNode")]
    public extern Node? NextNode();
}

