/// <summary>
/// User agents must create a DOMImplementation object whenever a document is created and associate it with that document.
/// </summary>
/// <remarks>
/// <see href="https://dom.spec.whatwg.org/#domimplementation">DOM Standard: 4.5.1 Interface DOMImplementation</see>
/// </remarks>
[ECMAScript]
[Description("@#DOMImplementation")]
public class DOMImplementation
{
    /// <summary>
    /// The DOMImplementation.createDocumentType() method returns a DocumentType object which can either be used with DOMImplementation.createDocument upon document creation or can be put into the document via methods like Node.insertBefore() or Node.replaceChild().
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createDocumentType">MDN Web Docs: DOMImplementation.createDocumentType</see>
    /// </remarks>
    /// <param name="name">A string containing the name of the doctype, like html. Corresponds to the DocumentType.name property. <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createDocumentType">MDN Web Docs: name</see></param>
    /// <param name="publicId">A string containing the PUBLIC identifier. Corresponds to the DocumentType.publicId property. <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createDocumentType">MDN Web Docs: publicId</see></param>
    /// <param name="systemId">A string containing the SYSTEM identifiers. Corresponds to the DocumentType.systemId property. <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createDocumentType">MDN Web Docs: systemId</see></param>
    /// <returns>A DocumentType.</returns>
    [Description("@#createDocumentType")]
    public extern DocumentType CreateDocumentType(string name, string publicId, string systemId);

    /// <summary>
    /// The createDocument() method of the DOMImplementation interface creates and returns an XMLDocument.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createDocument">MDN Web Docs: DOMImplementation.createDocument</see>
    /// </remarks>
    /// <param name="namespace"><see href="https://dom.spec.whatwg.org/#dom-domimplementation-createdocument-namespace-qualifiedname-doctype-namespace">DOM Standard: 4.5.1 Interface DOMImplementation</see></param>
    /// <param name="qualifiedName">A string containing the qualified name of the document to be created. A null value is treated the same as the empty string (&quot;&quot;). The format of the qualified name is prefix:localName or localName, where the parts are defined as: prefix Optional A &quot;short alias&quot; for the namespace. The prefix is optional, but if it is specified the namespaceURI parameter must also be specified. If the prefix is set to xml or xmlns, the namespaceURI must be set to http://www.w3.org/XML/1998/namespace or http://www.w3.org/2000/xmlns/, respectively. Defaults to null. localName The local name of the document. <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createDocument">MDN Web Docs: qualifiedName</see></param>
    /// <param name="doctype"><see href="https://dom.spec.whatwg.org/#dom-domimplementation-createdocument-namespace-qualifiedname-doctype-doctype">DOM Standard: 4.5.1 Interface DOMImplementation</see></param>
    /// <returns>The newly-created XMLDocument.</returns>
    [Description("@#createDocument")]
    public extern XMLDocument CreateDocument(string? @namespace, string qualifiedName, DocumentType? doctype = default);

    /// <summary>
    /// The DOMImplementation.createHTMLDocument() method creates a new HTML Document.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createHTMLDocument">MDN Web Docs: DOMImplementation.createHTMLDocument</see>
    /// </remarks>
    /// <param name="title">A string containing the title to give the new HTML document. <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/createHTMLDocument">MDN Web Docs: title</see></param>
    /// <returns>A new HTML Document object.</returns>
    [Description("@#createHTMLDocument")]
    public extern DocumentRef CreateHTMLDocument(string? title = default);

    /// <summary>
    /// The DOMImplementation.hasFeature() method returns a boolean flag indicating if a given feature is supported. It is deprecated and modern browsers return true in all cases. The different implementations fairly diverged in what kind of features were reported. The latest version of the spec settled to force this method to always return true, where the functionality was accurate and in use.
    /// </summary>
    /// <remarks>
    /// <see href="https://developer.mozilla.org/en-US/docs/Web/API/DOMImplementation/hasFeature">MDN Web Docs: DOMImplementation.hasFeature</see>
    /// </remarks>
    /// <returns>A boolean value of true.</returns>
    [Description("@#hasFeature")]
    public extern bool HasFeature();
}

/// <summary>
